def ajustar_respostas_antigas(apps, schema_editor):
    """Os Não do fluxo antigo (17/11): quem respondeu foi o próprio CN, então o
    de acordo já está dado; venda sem CN fica "sem CN"; o que o gerente
    respondeu por ele ganha as 24 h a partir da resposta (no mais, já vencidas,
    viram automáticas na primeira tela que abrir)."""
    Resposta = apps.get_model('contestacao', 'RespostaNaoContesta')
    for r in Resposta.objects.all().iterator():
        if r.cn_id is None:
            r.situacao_cn = 'sem_cn'
        elif r.preenchido_por_id == r.cn_id:
            r.situacao_cn = 'de_acordo'
            r.cn_respondido_em = r.atualizado_em
            r.cn_respondido_por_id = r.cn_id
        else:
            r.situacao_cn = 'aguardando'
            r.prazo_cn = r.atualizado_em + timedelta(hours=24)
        r.save(update_fields=['situacao_cn', 'cn_respondido_em', 'cn_respondido_por', 'prazo_cn'])


